CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  tenancy_row public.tenancies%rowtype;
begin
  select *
    into tenancy_row
  from public.tenancies
  where id = new.tenancy_id;

  if tenancy_row.id is null or tenancy_row.status <> 'ended' then
    raise exception 'Reviews are allowed only after an ended tenancy';
  end if;

  if new.reviewer_id = tenancy_row.tenant_id then
    if new.reviewee_id <> tenancy_row.landlord_id then
      raise exception 'Tenant may review only the landlord for this tenancy';
    end if;
  elsif new.reviewer_id = tenancy_row.landlord_id then
    if new.reviewee_id <> tenancy_row.tenant_id then
      raise exception 'Landlord may review only the tenant for this tenancy';
    end if;
  else
    raise exception 'Reviewer is not a party to this tenancy';
  end if;

  return new;
end;
$function$
